def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def step_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: manhattan(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = None
            best_key = None
            for t in targets:
                tp = pos(t, None)
                if tp is None:
                    continue
                d_self = manhattan(self_pos, tp)
                d_opp = manhattan(opp_pos, tp)
                key = (d_self, -d_opp)
                if best is None or key < best_key:
                    best = tp
                    best_key = key
            if best is not None:
                return step_toward(self_pos, best)
        # Fallback: pressure opponent while avoiding idle.
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = None
        best_key = None
        for r in resources:
            rp = pos(r, None)
            if rp is None:
                continue
            d_self = manhattan(self_pos, rp)
            d_opp = manhattan(opp_pos, rp)
            key = (d_self, d_opp)
            if best is None or key < best_key:
                best = rp
                best_key = key
        if best is not None:
            return step_toward(self_pos, best)

    # Generic fallback: move away from opponent unless already aligned, then keep still.
    return [-clamp_step(ox - sx), -clamp_step(oy - sy)]

